225			t.Fatalf("no measurements, got %v", err)
226		}
227		if _, err := s.SubmitSample("S1", "P1", at(1, 0), Measurement{Item: "pH", Value: math.Inf(-1)}); !errors.Is(err, ErrInvalidValue) {
228			t.Fatalf("-Inf, got %v", err)
229		}
230		if _, err := s.SubmitSample("S1", "P1", at(1, 0),
231			Measurement{Item: " pH ", Value: 7}, Measurement{Item: "pH", Value: 8}); !errors.Is(err, ErrDuplicateItem) {
