214		}
215		checkTwoItemSaved(t, before, "作废前确认")
216	
217		if _, err := s.Void("S1", "采样瓶破损"); err != nil {
218			t.Fatalf("Void: %v", err)
219		}
220	
221		checkVoided := func(smp Sample, label string) {
222			t.Helper()
223			if smp.Status != StatusVoided || smp.VoidReason != "采样瓶破损" {
224				t.Fatalf("%s: 作废状态或原因被改动: %+v", label, smp)
225			}
226			// 原测量与原判定结果（含逐项依据和整份超标标记）保留
227			if smp.ID != "S1" || smp.PointID != "P1" || !smp.SampledAt.Equal(at(10, 0)) {
228				t.Fatalf("%s: 基本字段被改动: %+v", label, smp)
229			}
230			if !smp.Exceeded || len(smp.Measurements) != 2 || len(smp.Results) != 2 {
231				t.Fatalf("%s: 原判定结果未保留: %+v", label, smp)
232			}
233			rs := map[string]ItemResult{}
234			for _, r := range smp.Results {
235				rs[r.Item] = r
236			}
237			if ph := rs["pH"]; ph.Value != 9 || ph.Limit != 8.0 || !ph.Exceeded {
238				t.Fatalf("%s: pH 原判定未保留: %+v", label, ph)
239			}
240			if cod := rs["COD"]; cod.Value != 30 || cod.Limit != 30.0 || cod.Exceeded {
241				t.Fatalf("%s: COD 原判定未保留: %+v", label, cod)
242			}
243		}
244	
245		list, err := s.ListByPoint("P1")
246		if err != nil || len(list) != 1 {
247			t.Fatalf("ListByPoint: %+v err=%v", list, err)
248		}
249		checkVoided(list[0], "作废后按点查询")
250	
251		// 作废前取得的已确认记录保持取得时的内容，不随作废操作变化
252		checkTwoItemSaved(t, before, "作废后先前取得的记录")
253	
254		// 调用方把查询得到的作废记录改回已确认、清空作废原因、伪造结论
255		forged := list[0]
256		forged.Status = StatusConfirmed
257		forged.VoidReason = ""
258		forged.Exceeded = false
259		forged.Results[0].Exceeded = false
260	
261		// 保存记录不能恢复有效：再次确认仍拒绝
262		if _, err := s.Confirm("S1"); !errors.Is(err, ErrVoided) {
263			t.Fatalf("已作废样品再次确认应拒绝, got %v", err)
264		}
265		// 最近有效结果继续排除该样品；没有其他有效结果时明确无结果
266		if latest, ok, err := s.LatestResult("P1"); err != nil || ok {
267			t.Fatalf("作废后应无最近有效结果: %+v ok=%v err=%v", latest, ok, err)
268		}
269		// 再次查询仍是作废记录，原测量、原判定与作废原因俱在
270		list2, err := s.ListByPoint("P1")
271		if err != nil || len(list2) != 1 {
272			t.Fatalf("伪造后 ListByPoint: %+v err=%v", list2, err)
273		}
274		checkVoided(list2[0], "伪造后再次查询")
275		// 正常重复作废（相同原因）仍返回保存的作废记录
276		again, err := s.Void("S1", "采样瓶破损")
277		if err != nil {
278			t.Fatalf("重复作废: %v", err)
279		}
280		checkVoided(again, "重复作废返回值")
281	}
